diff --git a/sistema/sistema.cpp b/sistema/sistema.cpp
index 761f866..a97d884 100644
--- a/sistema/sistema.cpp
+++ b/sistema/sistema.cpp
@@ -1993,6 +1993,122 @@ extern "C" void c_cedebug(natl id, const char *buf, natq quanti)
 //   ESAME 2024-01-10 )

 // ( SOLUZIONE 2024-01-10
+
+/// @brief Driver delle periferiche CE.
+///
+/// Gestisce le interruzioni provenienti da una periferica CE, leggendo
+/// un byte dal registro RBR e incrementando il semaforo di sincronizzazione.
+///
+/// @param id		id della periferica (0..MAX_CE-1)
+extern "C" void c_driver_ce(natl id)
+{
+	if (id >= next_ce)
+		return;
+
+	des_ce *ce = &array_ce[id];
+
+	// gestiamo l'interruzione solo se è in corso un trasferimento
+	if (!ce->enabled)
+		return;
+
+	// leggiamo un byte dal registro RBR
+	*ce->buf = inputb(ce->iRBR);
+	ce->buf++;
+	ce->quanti--;
+
+	// se abbiamo ancora byte da leggere, lasciamo l'interfaccia abilitata
+	// altrimenti la disabilitiamo e segnala al processo che l'operazione è completa
+	if (ce->quanti == 0) {
+		ce->enabled = false;
+		outputb(0, ce->iCTL);
+	}
+
+	sem_signal(ce->sync);
+}
+
+/// @brief Lettura di n byte da una periferica CE con timeout.
+///
+/// @param id		id della periferica
+/// @param buf		buffer di destinazione
+/// @param[in,out] quanti in: byte da leggere, out: byte effettivamente letti
+/// @param to		timeout in intervalli di tempo
+///
+/// @return 		true se lettura completata entro timeout, false altrimenti
+extern "C" bool c_ceread_n_to(natl id, char *buf, natq& quanti, natl to)
+{
+	// controllo timeout
+	if (!to) {
+		flog(LOG_WARN, "ceread_n_to: timeout zero");
+		c_abort_p();
+		return false;
+	}
+
+	// controllo id valido
+	if (id >= next_ce) {
+		flog(LOG_WARN, "ceread_n_to: id non valido: %u", id);
+		c_abort_p();
+		return false;
+	}
+
+	// controllo che il riferimento a quanti sia valido
+	if (!c_access(int_cast<vaddr>(&quanti), sizeof(natq), true, false)) {
+		flog(LOG_WARN, "ceread_n_to: Cavallo di Troia");
+		c_abort_p();
+		return false;
+	}
+
+	// controllo Cavallo di Troia per il buffer (deve essere scrivibile)
+	if (!c_access(int_cast<vaddr>(buf), quanti, true, false)) {
+		flog(LOG_WARN, "ceread_n_to: Cavallo di Troia");
+		c_abort_p();
+		return false;
+	}
+
+	des_ce *ce = &array_ce[id];
+
+	// acquisiamo la mutua esclusione con timeout
+	to = sem_wait_to(ce->mutex, to);
+	if (to == 0) {
+		// timeout scaduto mentre attendevamo la mutua esclusione
+		quanti = 0;
+		return false;
+	}
+
+	// impostiamo i parametri del trasferimento
+	ce->buf = buf;
+	ce->quanti = quanti;
+	ce->enabled = true;
+
+	// abilitiamo le interruzioni
+	outputb(1, ce->iCTL);
+
+	bool ok = true;
+	natl letti = 0;
+
+	// leggiamo un byte alla volta con timeout
+	for (natl i = 0; i < quanti; i++) {
+		to = sem_wait_to(ce->sync, to);
+		if (to == 0) {
+			// timeout: operazione annullata
+			ok = false;
+			break;
+		}
+		letti++;
+	}
+
+	// disabilitiamo le interruzioni e resettiamo lo stato
+	outputb(0, ce->iCTL);
+	ce->enabled = false;
+	ce->quanti = quanti - letti;
+
+	// aggiorniamo quanti con il numero di byte effettivamente letti
+	quanti = letti;
+
+	// rilasciamo la mutua esclusione
+	sem_signal(ce->mutex);
+
+	return ok;
+}
 //   SOLUZIONE 2024-01-10 )

