diff --git a/sistema/sistema.s b/sistema/sistema.s
index 84b43db..4dbfef3 100644
--- a/sistema/sistema.s
+++ b/sistema/sistema.s
@@ -243,6 +243,7 @@ init_idt:

 	carica_gate	TIPO_WTO	a_sem_wait_to	LIV_UTENTE
 	carica_gate	TIPO_CEDEBUG	a_cedebug	LIV_UTENTE
+	carica_gate	TIPO_CEREADTO	a_ceread_n_to	LIV_UTENTE
 //   ESAME 2024-01-10 )
 // ( SOLUZIONE 2024-01-10
 //   SOLUZIONE 2024-01-10 )
@@ -446,6 +447,19 @@ a_sem_wait_to:
 //   ESAME 2024-01-10 )

 // ( SOLUZIONE 2024-01-10
+
+	.extern c_ceread_n_to
+/// Parte Assembler della primitiva ceread_n_to()
+a_ceread_n_to:
+	.cfi_startproc
+	.cfi_def_cfa_offset 40
+	.cfi_offset rip, -40
+	.cfi_offset rsp, -16
+	call salva_stato
+	call c_ceread_n_to
+	call carica_stato
+	iretq
+	.cfi_endproc
 //   SOLUZIONE 2024-01-10 )

 /// @addtogroup pgsyscall
@@ -1552,6 +1566,13 @@ sem_wait_to:
 	ret
 	.cfi_endproc

+	.global sem_wait
+sem_wait:
+	.cfi_startproc
+	int $TIPO_W
+	ret
+	.cfi_endproc
+
 	.global sem_signal
 sem_signal:
 	.cfi_startproc
